def test_integrate_7_Inverse_hyperbolic_functions_7_1_Inverse_hyperbolic_sine_7_1_5_Inverse_hyperbolic_sine_functions_365():
    f = x/(sqrt(x**2 + 1)*asinh(x))
    F = sympy.Function('SinhIntegral')(sympy.asinh(x))
    assert integrate(f, x) == F


def test_integrate_7_Inverse_hyperbolic_functions_7_1_Inverse_hyperbolic_sine_7_1_5_Inverse_hyperbolic_sine_functions_366():
    f = x**3*asinh(a + b*x**4)
    F = (a + b*x**4)*asinh(a + b*x**4)/(4*b) - sqrt((a + b*x**4)**2 + 1)/(4*b)
    assert integrate(f, x) == F


def test_integrate_7_Inverse_hyperbolic_functions_7_1_Inverse_hyperbolic_sine_7_1_5_Inverse_hyperbolic_sine_functions_367():
    f = x**(n - 1)*asinh(a + b*x**n)
    F = (a + b*x**n)*asinh(a + b*x**n)/(b*n) - sqrt((a + b*x**n)**2 + 1)/(b*n)
    assert integrate(f, x) == F


def test_integrate_7_Inverse_hyperbolic_functions_7_1_Inverse_hyperbolic_sine_7_1_5_Inverse_hyperbolic_sine_functions_368():
    f = asinh(c/(a + b*x))
    F = c*atanh(sqrt(1 + (a/c + b*x/c)**(-2)))/b + (a + b*x)*acsch(a/c + b*x/c)/b
    assert integrate(f, x) == F


def test_integrate_7_Inverse_hyperbolic_functions_7_1_Inverse_hyperbolic_sine_7_1_5_Inverse_hyperbolic_sine_functions_369():
    f = x/asinh(sinh(x))
    F = (x*sqrt(cosh(x)**2)*sech(x) - asinh(sinh(x)))*log(asinh(sinh(x))) + asinh(sinh(x))
    assert integrate(f, x) == F


def test_integrate_7_Inverse_hyperbolic_functions_7_1_Inverse_hyperbolic_sine_7_1_5_Inverse_hyperbolic_sine_functions_370():
    f = asinh(sqrt(b*x**2 - 1))**n/sqrt(b*x**2 - 1)
    F = sqrt(b*x**2)*asinh(sqrt(b*x**2 - 1))**(n + 1)/(b*x*(n + 1))
    assert integrate(f, x) == F


def test_integrate_7_Inverse_hyperbolic_functions_7_1_Inverse_hyperbolic_sine_7_1_5_Inverse_hyperbolic_sine_functions_371():
    f = 1/(sqrt(b*x**2 - 1)*asinh(sqrt(b*x**2 - 1)))
    F = sqrt(b*x**2)*log(asinh(sqrt(b*x**2 - 1)))/(b*x)
    assert integrate(f, x) == F

